import{_ as e,o as i,c as a,ao as s}from"./chunks/framework.Cb4tnR4I.js";const g=JSON.parse('{"title":"Thunderbolt compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"guides/thunderbolt.md","filePath":"guides/thunderbolt.md","lastUpdated":null}'),n={name:"guides/thunderbolt.md"};function l(r,t,o,h,d,p){return i(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="Thunderbolt-compatibility" tabindex="-1">Thunderbolt compatibility <a class="header-anchor" href="#Thunderbolt-compatibility" aria-label="Permalink to &quot;Thunderbolt compatibility {#Thunderbolt-compatibility}&quot;">​</a></h1><p>FlashBang and <a href="https://github.com/JuliaHealth/Thunderbolt.jl" target="_blank" rel="noreferrer">Thunderbolt.jl</a> solve the same monodomain problem on different geometry: structured grids here, unstructured finite-element meshes there. FlashBang uses Thunderbolt&#39;s names for everything that describes the problem, so a model written for one reads the same in the other. Only the geometry and discretization lines change.</p><p>The difference is at the end. Thunderbolt&#39;s tutorials step the integrator by hand. FlashBang&#39;s primary API is SciML&#39;s <code>solve</code> (see <a href="./../getting_started">Getting Started</a>). The hand-driven form is still fully supported, and this page covers it.</p><h2 id="Shared-vocabulary" tabindex="-1">Shared vocabulary <a class="header-anchor" href="#Shared-vocabulary" aria-label="Permalink to &quot;Shared vocabulary {#Shared-vocabulary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Name</th><th style="text-align:right;">Role</th><th style="text-align:right;">Same in Thunderbolt</th></tr></thead><tbody><tr><td style="text-align:right;"><a href="/FlashBang.jl/dev/reference/api#FlashBang.MonodomainModel"><code>MonodomainModel</code></a></td><td style="text-align:right;">the continuous problem</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;"><a href="/FlashBang.jl/dev/reference/api#FlashBang.TransmembraneStimulationProtocol"><code>TransmembraneStimulationProtocol</code></a></td><td style="text-align:right;">the applied current</td><td style="text-align:right;">the name is shared, but in Thunderbolt it is the abstract type and the concrete analytic protocol is <code>AnalyticalTransmembraneStimulationProtocol</code></td></tr><tr><td style="text-align:right;"><a href="/FlashBang.jl/dev/reference/api#FlashBang.ReactionDiffusionSplit"><code>ReactionDiffusionSplit</code></a></td><td style="text-align:right;">how to split it</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;"><a href="/FlashBang.jl/dev/reference/api#FlashBang.semidiscretize-Union{Tuple{N}, Tuple{ReactionDiffusionSplit{&lt;:MonodomainModel}, FiniteDifferenceDiscretization, CartesianGrid{N}}} where N"><code>semidiscretize</code></a></td><td style="text-align:right;">builds the split function</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;"><code>OperatorSplittingProblem</code>, <code>LieTrotterGodunov</code></td><td style="text-align:right;">the split problem and algorithm (OrdinaryDiffEqOperatorSplitting)</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;"><a href="/FlashBang.jl/dev/reference/api#FlashBang.create_initial_condition-Tuple{GenericSplitFunction}"><code>create_initial_condition</code></a></td><td style="text-align:right;">every node at the cell model&#39;s default state</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;"><a href="/FlashBang.jl/dev/reference/api#FlashBang.getvariable-Tuple{Any, GenericSplitFunction, Symbol}"><code>getvariable</code></a>, <a href="/FlashBang.jl/dev/reference/api#FlashBang.setvariable!-Tuple{Any, Any, GenericSplitFunction, Symbol}"><code>setvariable!</code></a></td><td style="text-align:right;">named access to the state vector</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;"><code>CartesianGrid</code>, <a href="/FlashBang.jl/dev/reference/api#FlashBang.FiniteDifferenceDiscretization"><code>FiniteDifferenceDiscretization</code></a></td><td style="text-align:right;">geometry and discretization</td><td style="text-align:right;">no: these are the lines that change</td></tr></tbody></table><p>The solution vector also follows Thunderbolt&#39;s state-blocked layout (Thunderbolt calls it <code>StateBlockedLayout</code>), so a block of <code>u</code> means the same thing in both.</p><h2 id="Driving-the-integrator-directly" tabindex="-1">Driving the integrator directly <a class="header-anchor" href="#Driving-the-integrator-directly" aria-label="Permalink to &quot;Driving the integrator directly {#Driving-the-integrator-directly}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prob </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> OperatorSplittingProblem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(f, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">create_initial_condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(f), (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">400.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.005</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">integrator </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(prob, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">LieTrotterGodunov</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Euler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Euler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())); dt)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> _ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">round</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Int, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">400.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> /</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dt)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    step!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(integrator, dt, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    φ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> getvariable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(integrator</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u, f, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:φₘ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># a view, not a copy</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # ... inspect or modify the state between steps</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span></code></pre></div><p>Count steps rather than looping <code>while integrator.t &lt; 400.0</code>. Time accumulates rounding error, so <code>t</code> lands a hair below 400 after the last step and the <code>while</code> form takes one step too many. <code>solve</code> handles this itself and lands exactly on the end of <code>tspan</code>. That is also why its final state can differ slightly from a fixed-count loop&#39;s when <code>dt</code> is not exactly representable in binary: <code>solve</code> takes one extra, near-zero step to land on the end time.</p><p><code>solve!(integrator)</code> runs the remaining steps and returns the same solution object <code>solve</code> would, with the same <code>saveat</code> and <code>callback</code> behaviour.</p><h2 id="When-to-drive-it-by-hand" tabindex="-1">When to drive it by hand <a class="header-anchor" href="#When-to-drive-it-by-hand" aria-label="Permalink to &quot;When to drive it by hand {#When-to-drive-it-by-hand}&quot;">​</a></h2><p><code>solve</code> with a <a href="/FlashBang.jl/dev/reference/api#FlashBang.StateObserver-Tuple{Any}"><code>StateObserver</code></a> covers per-step reading: activation times, traces, movie frames. Step by hand when the loop has to do more than read:</p><ul><li><p><strong>Changing state mid-run</strong> with <a href="/FlashBang.jl/dev/reference/api#FlashBang.setvariable!-Tuple{Any, Any, GenericSplitFunction, Symbol}"><code>setvariable!</code></a> on <code>integrator.u</code> (an S2 written as a state reset rather than a stimulus current, for example). A callback can do this too, but then it must not call <code>derivative_discontinuity!(integrator, false)</code>, because the state really did change.</p></li><li><p><strong>Interactive or conditional stepping</strong>, such as advancing until a condition holds and then deciding what to do next.</p></li><li><p><strong>Porting a Thunderbolt script</strong> line for line before moving it to <code>solve</code>.</p></li></ul><h2 id="Names-on-an-integrator" tabindex="-1">Names on an integrator <a class="header-anchor" href="#Names-on-an-integrator" aria-label="Permalink to &quot;Names on an integrator {#Names-on-an-integrator}&quot;">​</a></h2><p>Symbolic indexing works on the integrator as well as on the solution. <code>integrator[:φₘ]</code> returns the voltage block. It copies on every call, though: at the 0.1 mm Niederer resolution that is 3.4 MB per call, so inside a stepping loop use <code>getvariable(integrator.u, f, :φₘ)</code>, which is a view.</p>`,15)])])}const k=e(n,[["render",l]]);export{g as __pageData,k as default};
